select p.proname,pg_get_function_identity_arguments(p.oid),p.prosecdef from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('update_material_usage_request','cancel_material_usage_request','get_material_usage_request_history');
select r.id,r.status,r.quantity_tons,coalesce(sum(a.quantity_tons) filter(where a.status in ('planned','confirmed')),0) allocated_tons from public.material_usage_requests r left join public.material_contract_allocations a on a.usage_request_id=r.id group by r.id having r.quantity_tons+0.00005<coalesce(sum(a.quantity_tons) filter(where a.status in ('planned','confirmed')),0);
select r.id,a.id,a.status from public.material_usage_requests r join public.material_contract_allocations a on a.usage_request_id=r.id where r.status='cancelled' and a.status in ('planned','confirmed');
select activity_type,metadata->>'usage_request_id' usage_request_id,count(*) from public.activity_logs where metadata ? 'usage_request_id' group by activity_type,metadata->>'usage_request_id' order by usage_request_id,activity_type;
